INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A dyeing recipe uses 1.5% owf of one dye and 0.6% owf of another for a combination shade, on a 550 kg fabric batch. What is the total combined dye weight needed?', '["11.55 kg","2.1 kg","8.25 kg","3.3 kg"]'::jsonb, '11.55 kg', 'Total %owf = 1.5 + 0.6 = 2.1%. Total dye = 0.021 × 550 kg = 11.55 kg.', 2, '{"combination-dye-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A recipe requires 4 g/L of a wetting agent at a liquor ratio of 1:20 for a 100 kg fabric batch. How many kg of wetting agent are needed?', '["8 kg","4 kg","20 kg","0.8 kg"]'::jsonb, '8 kg', 'Total liquor = 20 × 100 kg = 2,000 liters. Total wetting agent = 4 g/L × 2,000 L = 8,000 g = 8 kg.', 2, '{"wetting-agent-dosing-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A batch of 350 kg fabric is dyed with a liquor ratio of 1:9. If the recipe requires 3 g/L of a sequestering agent, how many kg total are needed?', '["9.45 kg","3 kg","9 kg","31.5 kg"]'::jsonb, '9.45 kg', 'Total liquor = 9 × 350 kg = 3,150 liters. Total sequestering agent = 3 g/L × 3,150 L = 9,450 g = 9.45 kg.', 2, '{"sequestering-agent-calc"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'A finishing chemical costs $3.50 per kg. If a recipe uses 4% add-on for a 600 kg fabric batch, what is the approximate total chemical cost?', '["≈ $84","≈ $3.50","≈ $24","≈ $2,100"]'::jsonb, '≈ $84', 'Chemical needed = 0.04 × 600 kg = 24 kg. Total cost = 24 kg × $3.50/kg = $84.', 2, '{"finishing-chemical-cost-calc"}'::text[]);
